29 29 def transform(grid):
    """Complete blank full-width horizontal bands by the shortest compatible cycle."""
    h, w = len(grid), len(grid[0])
    anchors = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            anchors[r] = row[0]
    if not anchors:
        return [row[:] for row in grid]
    period = h
    for p in range(1, h + 1):
        seen = {}
        valid = True
        for r, color in anchors.items():
            k = r % p
            if k in seen and seen[k] != color:
                valid = False
                break
            seen[k] = color
        if valid:
            period = p
            break
    pattern = {r % period: color for r, color in anchors.items()}
    out = []
    for r, row in enumerate(grid):
        color = pattern.get(r % period)
        out.append([color] * w if color is not None else row[:])
    return out
